namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Constructor_ValidArgs_SetsPageIndex()
    {
        // Arrange & Act
        var list = new PaginatedList<int>(new List<int> { 1, 2, 3 }, count: 30, pageIndex: 2, pageSize: 10);

        // Assert
        Assert.Equal(2, list.PageIndex);
    }

    [Fact]
    public void Constructor_ValidArgs_CalculatesTotalPages()
    {
        // Arrange & Act — 25 items, 10 per page → ceil(25/10) = 3
        var list = new PaginatedList<int>(new List<int> { 1 }, count: 25, pageIndex: 1, pageSize: 10);

        // Assert
        Assert.Equal(3, list.TotalPages);
    }

    [Fact]
    public void Constructor_CountNotDivisible_CeilsTotalPages()
    {
        // Arrange & Act — 21 items, 10 per page → ceil(21/10) = 3
        var list = new PaginatedList<int>(new List<int>(), count: 21, pageIndex: 1, pageSize: 10);

        // Assert
        Assert.Equal(3, list.TotalPages);
    }

    [Fact]
    public void Constructor_ExactlyDivisible_CorrectTotalPages()
    {
        // Arrange & Act — 30 items, 10 per page → ceil(30/10) = 3
        var list = new PaginatedList<int>(new List<int>(), count: 30, pageIndex: 1, pageSize: 10);

        // Assert
        Assert.Equal(3, list.TotalPages);
    }

    [Fact]
    public void Constructor_ValidArgs_ContainsAllItems()
    {
        // Arrange
        var items = new List<int> { 10, 20, 30 };

        // Act
        var list = new PaginatedList<int>(items, count: 30, pageIndex: 1, pageSize: 10);

        // Assert
        Assert.Equal(3, list.Count);
        Assert.Contains(10, list);
        Assert.Contains(20, list);
        Assert.Contains(30, list);
    }

    [Fact]
    public void HasPreviousPage_FirstPage_ReturnsFalse()
    {
        // Arrange
        var list = new PaginatedList<int>(new List<int>(), count: 30, pageIndex: 1, pageSize: 10);

        // Assert
        Assert.False(list.HasPreviousPage);
        Assert.Equal(1, list.PageIndex);
    }

    [Fact]
    public void HasPreviousPage_SecondPage_ReturnsTrue()
    {
        // Arrange
        var list = new PaginatedList<int>(new List<int>(), count: 30, pageIndex: 2, pageSize: 10);

        // Assert
        Assert.True(list.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_LastPage_ReturnsFalse()
    {
        // Arrange — 30 items, 10/page → 3 pages, on page 3
        var list = new PaginatedList<int>(new List<int>(), count: 30, pageIndex: 3, pageSize: 10);

        // Assert
        Assert.False(list.HasNextPage);
        Assert.Equal(list.PageIndex, list.TotalPages);
    }

    [Fact]
    public void HasNextPage_NotLastPage_ReturnsTrue()
    {
        // Arrange — 30 items, 10/page → 3 pages, on page 1
        var list = new PaginatedList<int>(new List<int>(), count: 30, pageIndex: 1, pageSize: 10);

        // Assert
        Assert.True(list.HasNextPage);
        Assert.True(list.PageIndex < list.TotalPages);
    }

    [Fact]
    public void HasPreviousPage_And_HasNextPage_MiddlePage()
    {
        // Arrange — page 2 of 3
        var list = new PaginatedList<int>(new List<int>(), count: 30, pageIndex: 2, pageSize: 10);

        // Assert — middle page has both
        Assert.True(list.HasPreviousPage);
        Assert.True(list.HasNextPage);
    }

    [Fact]
    public void Create_FirstPage_ReturnsCorrectItems()
    {
        // Arrange
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        // Assert
        Assert.Equal(10, result.Count);
        Assert.Equal(1, result[0]);
        Assert.Equal(10, result[9]);
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
    }

    [Fact]
    public void Create_MiddlePage_SkipsCorrectly()
    {
        // Arrange
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

        // Assert
        Assert.Equal(10, result.Count);
        Assert.Equal(11, result[0]);
        Assert.Equal(20, result[9]);
    }

    [Fact]
    public void Create_LastPage_ReturnsRemainingItems()
    {
        // Arrange
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, pageIndex: 3, pageSize: 10);

        // Assert
        Assert.Equal(5, result.Count);
        Assert.Equal(21, result[0]);
        Assert.Equal(25, result[4]);
        Assert.Equal(3, result.TotalPages);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyList()
    {
        // Arrange
        var source = Enumerable.Empty<int>().AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        // Assert
        Assert.Empty(result);
        Assert.Equal(0, result.TotalPages);
    }

    [Fact]
    public void Create_SinglePage_ReturnsAllItems()
    {
        // Arrange
        var source = Enumerable.Range(1, 5).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        // Assert
        Assert.Equal(5, result.Count);
        Assert.Equal(1, result.TotalPages);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void Constructor_SingleItem_SinglePage()
    {
        // Arrange & Act
        var list = new PaginatedList<string>(new List<string> { "only" }, count: 1, pageIndex: 1, pageSize: 10);

        // Assert
        Assert.Equal(1, list.TotalPages);
        Assert.Single(list);
        Assert.False(list.HasPreviousPage);
        Assert.False(list.HasNextPage);
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _service;

    public NotificationServiceTests()
    {
        _service = new NotificationService();
        // Drain the static queue to isolate tests
        while (_service.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain again after test to avoid contamination
        while (_service.ReceiveNotification() != null) { }
        _service.Dispose();
    }

    // --- SendNotification (4-param overload) ---

    [Fact]
    public void SendNotification_4Param_EnqueuesNotification()
    {
        // Act
        _service.SendNotification("Student", "1", EntityOperation.CREATE, "Admin");
        var notification = _service.ReceiveNotification();

        // Assert
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
    }

    [Fact]
    public void SendNotification_WithUserName_SetsCreatedBy()
    {
        // Act
        _service.SendNotification("Course", "101", EntityOperation.UPDATE, "Admin");
        var notification = _service.ReceiveNotification();

        // Assert
        Assert.NotNull(notification);
        Assert.Equal("Admin", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_WithoutUserName_DefaultsToSystem()
    {
        // Act — userName defaults to null
        _service.SendNotification("Course", "101", EntityOperation.CREATE);
        var notification = _service.ReceiveNotification();

        // Assert
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    // --- SendNotification (5-param overload) ---

    [Fact]
    public void SendNotification_WithDisplayName_SetsMessageWithDisplayName()
    {
        // Act
        _service.SendNotification("Department", "5", "Engineering", EntityOperation.CREATE, "Admin");
        var notification = _service.ReceiveNotification();

        // Assert
        Assert.NotNull(notification);
        Assert.Contains("'Engineering'", notification.Message);
        Assert.Contains("Department", notification.Message);
    }

    [Fact]
    public void SendNotification_SetsEntityTypeAndId()
    {
        // Act
        _service.SendNotification("Instructor", "42", "Dr. Smith", EntityOperation.UPDATE, "TestUser");
        var notification = _service.ReceiveNotification();

        // Assert
        Assert.Equal("Instructor", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
    }

    [Fact]
    public void SendNotification_SetsOperationString()
    {
        // Act
        _service.SendNotification("Student", "1", EntityOperation.CREATE);
        var notification = _service.ReceiveNotification();

        // Assert
        Assert.Equal("CREATE", notification.Operation);
    }

    [Fact]
    public void SendNotification_SetsIsReadFalse()
    {
        // Act
        _service.SendNotification("Course", "10", EntityOperation.DELETE);
        var notification = _service.ReceiveNotification();

        // Assert
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToRecentTime()
    {
        // Arrange
        var before = DateTime.Now.AddSeconds(-1);

        // Act
        _service.SendNotification("Student", "1", EntityOperation.CREATE);
        var notification = _service.ReceiveNotification();

        // Assert
        var after = DateTime.Now.AddSeconds(1);
        Assert.InRange(notification.CreatedAt, before, after);
    }

    // --- ReceiveNotification ---

    [Fact]
    public void ReceiveNotification_WhenEmpty_ReturnsNull()
    {
        // Act
        var result = _service.ReceiveNotification();

        // Assert
        Assert.Null(result);
    }

    [Fact]
    public void ReceiveNotification_AfterSend_ReturnsNotification()
    {
        // Arrange
        _service.SendNotification("Student", "1", EntityOperation.CREATE);

        // Act
        var result = _service.ReceiveNotification();

        // Assert
        Assert.NotNull(result);
        Assert.Equal("Student", result.EntityType);
    }

    [Fact]
    public void ReceiveNotification_FIFO_ReturnsInOrder()
    {
        // Arrange
        _service.SendNotification("First", "1", EntityOperation.CREATE);
        _service.SendNotification("Second", "2", EntityOperation.UPDATE);

        // Act
        var first = _service.ReceiveNotification();
        var second = _service.ReceiveNotification();

        // Assert
        Assert.Equal("First", first.EntityType);
        Assert.Equal("Second", second.EntityType);
        Assert.Equal("1", first.EntityId);
        Assert.Equal("2", second.EntityId);
    }

    [Fact]
    public void ReceiveNotification_DrainsQueue_SubsequentCallReturnsNull()
    {
        // Arrange
        _service.SendNotification("Only", "1", EntityOperation.CREATE);
        _service.ReceiveNotification(); // drain

        // Act
        var result = _service.ReceiveNotification();

        // Assert
        Assert.Null(result);
    }

    // --- MarkAsRead ---

    [Fact]
    public void MarkAsRead_AnyId_DoesNotThrow()
    {
        // Act & Assert — no-op should not throw
        var exception = Record.Exception(() => _service.MarkAsRead(999));
        Assert.Null(exception);
    }

    [Fact]
    public void MarkAsRead_NegativeId_DoesNotThrow()
    {
        var exception = Record.Exception(() => _service.MarkAsRead(-1));
        Assert.Null(exception);
    }

    // --- GenerateMessage (tested indirectly via SendNotification) ---

    [Fact]
    public void SendNotification_CreateOp_MessageContainsCreated()
    {
        // Act
        _service.SendNotification("Student", "1", EntityOperation.CREATE);
        var notification = _service.ReceiveNotification();

        // Assert
        Assert.Contains("has been created", notification.Message);
        Assert.StartsWith("New ", notification.Message);
    }

    [Fact]
    public void SendNotification_UpdateOp_MessageContainsUpdated()
    {
        // Act
        _service.SendNotification("Course", "5", EntityOperation.UPDATE);
        var notification = _service.ReceiveNotification();

        // Assert
        Assert.Contains("has been updated", notification.Message);
        Assert.DoesNotContain("New ", notification.Message);
    }

    [Fact]
    public void SendNotification_DeleteOp_MessageContainsDeleted()
    {
        // Act
        _service.SendNotification("Department", "3", EntityOperation.DELETE);
        var notification = _service.ReceiveNotification();

        // Assert
        Assert.Contains("has been deleted", notification.Message);
        Assert.DoesNotContain("New ", notification.Message);
    }

    [Fact]
    public void SendNotification_WithDisplayName_MessageUsesDisplayName()
    {
        // Act
        _service.SendNotification("Course", "101", "Chemistry", EntityOperation.CREATE, "TestUser");
        var notification = _service.ReceiveNotification();

        // Assert — uses "Course 'Chemistry'" format, not ID format
        Assert.Contains("'Chemistry'", notification.Message);
        Assert.DoesNotContain("(ID:", notification.Message);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_MessageUsesIdFormat()
    {
        // Act — 4-param overload (no display name → null)
        _service.SendNotification("Student", "42", EntityOperation.UPDATE);
        var notification = _service.ReceiveNotification();

        // Assert — uses "Student (ID: 42)" format
        Assert.Contains("(ID: 42)", notification.Message);
        Assert.DoesNotContain("'", notification.Message);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "CREATE")]
    [InlineData(EntityOperation.UPDATE, "UPDATE")]
    [InlineData(EntityOperation.DELETE, "DELETE")]
    public void SendNotification_AllOperations_SetsCorrectOperationString(EntityOperation op, string expected)
    {
        // Act
        _service.SendNotification("Entity", "1", op);
        var notification = _service.ReceiveNotification();

        // Assert
        Assert.Equal(expected, notification.Operation);
    }

    // --- Dispose ---

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        // Arrange
        var service = new NotificationService();

        // Act & Assert
        var exception = Record.Exception(() => service.Dispose());
        Assert.Null(exception);
    }

    [Fact]
    public void Dispose_CalledMultipleTimes_DoesNotThrow()
    {
        // Arrange
        var service = new NotificationService();

        // Act & Assert
        var exception = Record.Exception(() =>
        {
            service.Dispose();
            service.Dispose();
        });
        Assert.Null(exception);
    }
}

