namespace ContosoUniversity.Tests.Data;

public class SchoolContextTests
{
    [Fact]
    public void SchoolContext_HasDbSet_Students()
    {
        using var context = TestHelpers.CreateInMemoryContext();
        DbSet<Student> dbSet = context.Students;
        Assert.NotNull(dbSet);
        // Verify it's queryable (not just a property stub)
        Assert.Equal(0, dbSet.Count());
    }

    [Fact]
    public void SchoolContext_HasDbSet_Courses()
    {
        using var context = TestHelpers.CreateInMemoryContext();
        DbSet<Course> dbSet = context.Courses;
        Assert.NotNull(dbSet);
        Assert.Equal(0, dbSet.Count());
    }

    [Fact]
    public void SchoolContext_HasDbSet_Departments()
    {
        using var context = TestHelpers.CreateInMemoryContext();
        DbSet<Department> dbSet = context.Departments;
        Assert.NotNull(dbSet);
        Assert.Equal(0, dbSet.Count());
    }

    [Fact]
    public void SchoolContext_HasDbSet_Enrollments()
    {
        using var context = TestHelpers.CreateInMemoryContext();
        DbSet<Enrollment> dbSet = context.Enrollments;
        Assert.NotNull(dbSet);
        Assert.Equal(0, dbSet.Count());
    }

    [Fact]
    public void SchoolContext_HasDbSet_Instructors()
    {
        using var context = TestHelpers.CreateInMemoryContext();
        DbSet<Instructor> dbSet = context.Instructors;
        Assert.NotNull(dbSet);
        Assert.Equal(0, dbSet.Count());
    }

    [Fact]
    public void SchoolContext_HasDbSet_Notifications()
    {
        using var context = TestHelpers.CreateInMemoryContext();
        DbSet<Notification> dbSet = context.Notifications;
        Assert.NotNull(dbSet);
        Assert.Equal(0, dbSet.Count());
    }

    [Fact]
    public void SchoolContext_HasDbSet_OfficeAssignments()
    {
        using var context = TestHelpers.CreateInMemoryContext();
        DbSet<OfficeAssignment> dbSet = context.OfficeAssignments;
        Assert.NotNull(dbSet);
        Assert.Equal(0, dbSet.Count());
    }

    [Fact]
    public void SchoolContext_HasDbSet_CourseAssignments()
    {
        using var context = TestHelpers.CreateInMemoryContext();
        DbSet<CourseAssignment> dbSet = context.CourseAssignments;
        Assert.NotNull(dbSet);
        Assert.Equal(0, dbSet.Count());
    }

    [Fact]
    public void SchoolContext_HasDbSet_People()
    {
        using var context = TestHelpers.CreateInMemoryContext();
        DbSet<Person> dbSet = context.People;
        Assert.NotNull(dbSet);
        Assert.Equal(0, dbSet.Count());
    }

    [Fact]
    public void SchoolContext_CourseAssignment_HasCompositeKey()
    {
        using var context = TestHelpers.CreateInMemoryContext();
        var entityType = context.Model.FindEntityType(typeof(CourseAssignment));

        Assert.NotNull(entityType);
        var primaryKey = entityType.FindPrimaryKey();
        Assert.NotNull(primaryKey);

        var keyPropertyNames = primaryKey.Properties.Select(p => p.Name).ToList();
        Assert.Equal(2, keyPropertyNames.Count);
        Assert.Contains("CourseID", keyPropertyNames);
        Assert.Contains("InstructorID", keyPropertyNames);
    }

    [Fact]
    public void SchoolContext_Person_HasTPHDiscriminator()
    {
        using var context = TestHelpers.CreateInMemoryContext();
        var personType = context.Model.FindEntityType(typeof(Person));
        Assert.NotNull(personType);

        var discriminator = personType.FindDiscriminatorProperty();
        Assert.NotNull(discriminator);
        Assert.Equal("Discriminator", discriminator.Name);
    }

    [Fact]
    public void SchoolContext_InstructorOfficeAssignment_OneToOneRelationship()
    {
        using var context = TestHelpers.CreateInMemoryContext();
        var officeType = context.Model.FindEntityType(typeof(OfficeAssignment));
        Assert.NotNull(officeType);

        // OfficeAssignment uses InstructorID as its primary key (1:1 with Instructor)
        var pk = officeType.FindPrimaryKey();
        Assert.NotNull(pk);
        Assert.Single(pk.Properties);
        Assert.Equal("InstructorID", pk.Properties[0].Name);
    }

    [Fact]
    public void SchoolContext_CanAddAndRetrieveStudent()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "User",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };
        context.Students.Add(student);
        context.SaveChanges();

        var retrieved = context.Students.Single();
        Assert.Equal("Test", retrieved.FirstMidName);
        Assert.Equal("User", retrieved.LastName);
        Assert.Equal(new DateTime(2023, 9, 1), retrieved.EnrollmentDate);
        // Verify ID was auto-generated
        Assert.NotEqual(0, retrieved.ID);
    }

    [Fact]
    public void SchoolContext_CanAddAndRetrieveInstructor()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        var instructor = new Instructor
        {
            FirstMidName = "Jane",
            LastName = "Doe",
            HireDate = new DateTime(2020, 1, 15)
        };
        context.Instructors.Add(instructor);
        context.SaveChanges();

        var retrieved = context.Instructors.Single();
        Assert.Equal("Jane", retrieved.FirstMidName);
        Assert.Equal("Doe", retrieved.LastName);
        Assert.Equal(new DateTime(2020, 1, 15), retrieved.HireDate);
    }

    [Fact]
    public void SchoolContext_StudentAndInstructor_SharePeopleTable_ViaTPH()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        context.Students.Add(new Student
        {
            FirstMidName = "Alice",
            LastName = "Student",
            EnrollmentDate = new DateTime(2023, 9, 1)
        });
        context.Instructors.Add(new Instructor
        {
            FirstMidName = "Bob",
            LastName = "Teacher",
            HireDate = new DateTime(2020, 1, 1)
        });
        context.SaveChanges();

        // Both should appear in the People DbSet (TPH: single table for Person hierarchy)
        Assert.Equal(2, context.People.Count());
        // But typed sets only show their own type
        Assert.Equal(1, context.Students.Count());
        Assert.Equal(1, context.Instructors.Count());
    }

    [Fact]
    public void SchoolContext_CourseAssignment_Relationships_ConfiguredCorrectly()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        var instructor = new Instructor
        {
            FirstMidName = "Test",
            LastName = "Inst",
            HireDate = new DateTime(2020, 1, 1)
        };
        context.Instructors.Add(instructor);
        context.SaveChanges();

        var course = new Course
        {
            CourseID = 1001,
            Title = "Test Course",
            Credits = 3,
            DepartmentID = 0
        };
        context.Courses.Add(course);
        context.SaveChanges();

        var assignment = new CourseAssignment
        {
            CourseID = course.CourseID,
            InstructorID = instructor.ID
        };
        context.CourseAssignments.Add(assignment);
        context.SaveChanges();

        var retrieved = context.CourseAssignments.Single();
        Assert.Equal(course.CourseID, retrieved.CourseID);
        Assert.Equal(instructor.ID, retrieved.InstructorID);
    }

    [Fact]
    public void SchoolContext_CanAddEnrollment_WithGrade()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        var student = new Student
        {
            FirstMidName = "A",
            LastName = "B",
            EnrollmentDate = new DateTime(2023, 1, 1)
        };
        context.Students.Add(student);
        var course = new Course { CourseID = 5000, Title = "Test", Credits = 3, DepartmentID = 0 };
        context.Courses.Add(course);
        context.SaveChanges();

        var enrollment = new Enrollment
        {
            StudentID = student.ID,
            CourseID = course.CourseID,
            Grade = Grade.A
        };
        context.Enrollments.Add(enrollment);
        context.SaveChanges();

        var retrieved = context.Enrollments.Single();
        Assert.Equal(Grade.A, retrieved.Grade);
        Assert.Equal(student.ID, retrieved.StudentID);
        Assert.Equal(course.CourseID, retrieved.CourseID);
    }

    [Fact]
    public void SchoolContext_CanAddEnrollment_WithNullGrade()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        var student = new Student
        {
            FirstMidName = "C",
            LastName = "D",
            EnrollmentDate = new DateTime(2023, 1, 1)
        };
        context.Students.Add(student);
        var course = new Course { CourseID = 6000, Title = "NoGrade", Credits = 2, DepartmentID = 0 };
        context.Courses.Add(course);
        context.SaveChanges();

        var enrollment = new Enrollment
        {
            StudentID = student.ID,
            CourseID = course.CourseID,
            Grade = null
        };
        context.Enrollments.Add(enrollment);
        context.SaveChanges();

        var retrieved = context.Enrollments.Single();
        Assert.Null(retrieved.Grade);
    }
}

using ContosoUniversity.Data;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Data;

public class DbInitializerTests
{
    private SchoolContext CreateSeededContext(string dbName = null)
    {
        var context = TestHelpers.CreateInMemoryContext(dbName ?? Guid.NewGuid().ToString());
        DbInitializer.Initialize(context);
        return context;
    }

    [Fact]
    public void Initialize_EmptyDatabase_Seeds8Students()
    {
        using var context = CreateSeededContext();

        var students = context.Students.ToList();
        Assert.Equal(8, students.Count);
        // Verify specific students exist with expected names
        Assert.Contains(students, s => s.LastName == "Alexander" && s.FirstMidName == "Carson");
        Assert.Contains(students, s => s.LastName == "Olivetto" && s.FirstMidName == "Nino");
    }

    [Fact]
    public void Initialize_EmptyDatabase_Seeds5Instructors()
    {
        using var context = CreateSeededContext();

        var instructors = context.Instructors.ToList();
        Assert.Equal(5, instructors.Count);
        Assert.Contains(instructors, i => i.LastName == "Abercrombie" && i.FirstMidName == "Kim");
        Assert.Contains(instructors, i => i.LastName == "Zheng" && i.FirstMidName == "Roger");
    }

    [Fact]
    public void Initialize_EmptyDatabase_Seeds4Departments()
    {
        using var context = CreateSeededContext();

        var departments = context.Departments.ToList();
        Assert.Equal(4, departments.Count);

        var english = departments.Single(d => d.Name == "English");
        Assert.Equal(350000m, english.Budget);

        var math = departments.Single(d => d.Name == "Mathematics");
        Assert.Equal(100000m, math.Budget);

        Assert.Contains(departments, d => d.Name == "Engineering");
        Assert.Contains(departments, d => d.Name == "Economics");
    }

    [Fact]
    public void Initialize_EmptyDatabase_Seeds7Courses()
    {
        using var context = CreateSeededContext();

        var courses = context.Courses.ToList();
        Assert.Equal(7, courses.Count);

        // Verify specific courses with their IDs and credits
        var chemistry = courses.Single(c => c.CourseID == 1050);
        Assert.Equal("Chemistry", chemistry.Title);
        Assert.Equal(3, chemistry.Credits);

        var calculus = courses.Single(c => c.CourseID == 1045);
        Assert.Equal("Calculus", calculus.Title);
        Assert.Equal(4, calculus.Credits);

        var literature = courses.Single(c => c.CourseID == 2042);
        Assert.Equal("Literature", literature.Title);
        Assert.Equal(4, literature.Credits);
    }

    [Fact]
    public void Initialize_EmptyDatabase_Seeds11Enrollments()
    {
        using var context = CreateSeededContext();

        var enrollments = context.Enrollments.ToList();
        Assert.Equal(11, enrollments.Count);

        // Verify at least one enrollment has a grade and one does not
        Assert.Contains(enrollments, e => e.Grade == Grade.A);
        Assert.Contains(enrollments, e => e.Grade == null);
    }

    [Fact]
    public void Initialize_EmptyDatabase_Seeds3OfficeAssignments()
    {
        using var context = CreateSeededContext();

        var officeAssignments = context.OfficeAssignments.ToList();
        Assert.Equal(3, officeAssignments.Count);
        Assert.Contains(officeAssignments, o => o.Location == "Smith 17");
        Assert.Contains(officeAssignments, o => o.Location == "Gowan 27");
        Assert.Contains(officeAssignments, o => o.Location == "Thompson 304");
    }

    [Fact]
    public void Initialize_EmptyDatabase_Seeds8CourseAssignments()
    {
        using var context = CreateSeededContext();

        var courseAssignments = context.CourseAssignments.ToList();
        Assert.Equal(8, courseAssignments.Count);
    }

    [Fact]
    public void Initialize_CalledTwice_IsIdempotent()
    {
        var dbName = Guid.NewGuid().ToString();
        using var context = TestHelpers.CreateInMemoryContext(dbName);

        DbInitializer.Initialize(context);
        DbInitializer.Initialize(context);

        // Counts should remain the same after the second call
        Assert.Equal(8, context.Students.Count());
        Assert.Equal(5, context.Instructors.Count());
        Assert.Equal(4, context.Departments.Count());
        Assert.Equal(7, context.Courses.Count());
        Assert.Equal(11, context.Enrollments.Count());
        Assert.Equal(3, context.OfficeAssignments.Count());
        Assert.Equal(8, context.CourseAssignments.Count());
    }

    [Fact]
    public void Initialize_DepartmentsLinkedToInstructors()
    {
        using var context = CreateSeededContext();

        var departments = context.Departments.ToList();
        var instructors = context.Instructors.ToList();

        // Every department should have a non-null InstructorID
        Assert.All(departments, d => Assert.NotNull(d.InstructorID));

        // English department should be assigned to Abercrombie
        var english = departments.Single(d => d.Name == "English");
        var abercrombie = instructors.Single(i => i.LastName == "Abercrombie");
        Assert.Equal(abercrombie.ID, english.InstructorID);
    }

    [Fact]
    public void Initialize_CoursesLinkedToDepartments()
    {
        using var context = CreateSeededContext();

        var courses = context.Courses.ToList();
        var departments = context.Departments.ToList();

        // Chemistry (1050) → Engineering
        var chemistry = courses.Single(c => c.CourseID == 1050);
        var engineering = departments.Single(d => d.Name == "Engineering");
        Assert.Equal(engineering.DepartmentID, chemistry.DepartmentID);

        // Microeconomics (4022) → Economics
        var micro = courses.Single(c => c.CourseID == 4022);
        var economics = departments.Single(d => d.Name == "Economics");
        Assert.Equal(economics.DepartmentID, micro.DepartmentID);
    }

    [Fact]
    public void Initialize_StudentsHaveCorrectEnrollmentDates()
    {
        using var context = CreateSeededContext();

        var students = context.Students.ToList();
        var alexander = students.Single(s => s.LastName == "Alexander");
        Assert.Equal(DateTime.Parse("2010-09-01"), alexander.EnrollmentDate);

        var olivetto = students.Single(s => s.LastName == "Olivetto");
        Assert.Equal(DateTime.Parse("2005-09-01"), olivetto.EnrollmentDate);
    }

    [Fact]
    public void Initialize_DatabaseWithExistingStudents_DoesNotSeedAgain()
    {
        var dbName = Guid.NewGuid().ToString();
        using var context = TestHelpers.CreateInMemoryContext(dbName);

        // Manually add one student before Initialize
        context.Students.Add(new Student
        {
            FirstMidName = "Pre",
            LastName = "Existing",
            EnrollmentDate = new DateTime(2024, 1, 1)
        });
        context.SaveChanges();

        DbInitializer.Initialize(context);

        // Should only have the pre-existing student — initializer returns early
        Assert.Equal(1, context.Students.Count());
        Assert.Equal(0, context.Courses.Count());
        Assert.Equal(0, context.Departments.Count());
    }
}

