using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
        _controller = new StudentsController(_context);

        // Set up TempData for controller
        _controller.TempData = new TempDataDictionary(
            new DefaultHttpContext(),
            Mock.Of<ITempDataProvider>());
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private void SeedStudents()
    {
        _context.Students.AddRange(
            new Student { LastName = "Alexander", FirstMidName = "Carson", EnrollmentDate = new DateTime(2020, 9, 1) },
            new Student { LastName = "Alonso", FirstMidName = "Meredith", EnrollmentDate = new DateTime(2021, 9, 1) },
            new Student { LastName = "Barzdukas", FirstMidName = "Gytis", EnrollmentDate = new DateTime(2019, 9, 1) },
            new Student { LastName = "Li", FirstMidName = "Yan", EnrollmentDate = new DateTime(2022, 9, 1) },
            new Student { LastName = "Justice", FirstMidName = "Peggy", EnrollmentDate = new DateTime(2020, 9, 1) }
        );
        _context.SaveChanges();
    }

    // --- Index ---

    [Fact]
    public void Index_NoParams_ReturnsViewWithStudentsOrderedByLastName()
    {
        SeedStudents();

        var result = _controller.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
        Assert.Equal(5, model.Count);
        // Default sort is OrderBy(LastName) ascending
        Assert.Equal("Alexander", model[0].LastName);
        Assert.Equal("Alonso", model[1].LastName);
        Assert.Equal("Barzdukas", model[2].LastName);
        Assert.Equal("Justice", model[3].LastName);
        Assert.Equal("Li", model[4].LastName);
    }

    [Fact]
    public void Index_NameDescSort_ReturnsStudentsDescendingByLastName()
    {
        SeedStudents();

        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Li", model[0].LastName);
        Assert.Equal("Justice", model[1].LastName);
        Assert.Equal("Barzdukas", model[2].LastName);
    }

    [Fact]
    public void Index_DateSort_ReturnsStudentsOrderedByDateAscending()
    {
        SeedStudents();

        var result = _controller.Index("Date", null, null, null) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        // 2019, 2020, 2020, 2021, 2022
        Assert.Equal("Barzdukas", model[0].LastName);
        Assert.Equal("Li", model[^1].LastName); // 2022 is last
    }

    [Fact]
    public void Index_DateDescSort_ReturnsStudentsDescendingByDate()
    {
        SeedStudents();

        var result = _controller.Index("date_desc", null, null, null) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Li", model[0].LastName); // 2022 first
        Assert.Equal("Barzdukas", model[^1].LastName); // 2019 last
    }

    [Fact]
    public void Index_WithSearchString_FiltersStudentsByLastName()
    {
        SeedStudents();

        var result = _controller.Index(null, null, "Alex", null) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_WithSearchString_FiltersStudentsByFirstName()
    {
        SeedStudents();

        var result = _controller.Index(null, null, "Yan", null) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Li", model[0].LastName);
    }

    [Fact]
    public void Index_NewSearch_ResetsPageTo1()
    {
        SeedStudents();

        // When searchString is non-null, page is reset to 1
        var result = _controller.Index(null, null, "Al", 5) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_NullSearch_UsesCurrentFilter()
    {
        SeedStudents();

        // When searchString is null, currentFilter is used instead
        var result = _controller.Index(null, "Alex", null, null) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_SetsViewBagSortParameters()
    {
        SeedStudents();

        _controller.Index(null, null, null, null);

        // Default sort: NameSortParm = "name_desc", DateSortParm = "Date"
        Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
        Assert.Equal("Date", _controller.ViewBag.DateSortParm);
    }

    [Fact]
    public void Index_Page2_ReturnsSecondPage()
    {
        // Seed more than 10 students (page size is 10)
        for (int i = 0; i < 15; i++)
        {
            _context.Students.Add(new Student
            {
                LastName = $"Student{i:D2}",
                FirstMidName = "Test",
                EnrollmentDate = DateTime.Today
            });
        }
        _context.SaveChanges();

        var result = _controller.Index(null, null, null, 2) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Equal(2, model.PageIndex);
        Assert.Equal(5, model.Count); // 15 total - 10 on page 1 = 5
        Assert.True(model.HasPreviousPage);
        Assert.False(model.HasNextPage);
    }

    // --- Details ---

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithStudent()
    {
        SeedStudents();
        var student = _context.Students.First();

        var result = _controller.Details(student.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
        Assert.Equal(student.LastName, model.LastName);
    }

    [Fact]
    public void Details_ValidId_IncludesEnrollments()
    {
        var student = new Student
        {
            LastName = "TestStudent",
            FirstMidName = "Test",
            EnrollmentDate = DateTime.Today
        };
        _context.Students.Add(student);
        _context.SaveChanges();

        var dept = new Department { Name = "Test", Budget = 100, StartDate = DateTime.Today };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 1001, Title = "Test Course", Credits = 3, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var enrollment = new Enrollment { StudentID = student.ID, CourseID = course.CourseID, Grade = Grade.A };
        _context.Enrollments.Add(enrollment);
        _context.SaveChanges();

        var result = _controller.Details(student.ID) as ViewResult;

        var model = Assert.IsType<Student>(result!.Model);
        Assert.NotNull(model.Enrollments);
        Assert.Single(model.Enrollments);
        Assert.Equal(Grade.A, model.Enrollments.First().Grade);
    }

    // --- Create GET ---

    [Fact]
    public void CreateGet_ReturnsViewWithStudentDefaultDate()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    // --- Create POST ---

    [Fact]
    public void CreatePost_ValidStudent_RedirectsToIndex()
    {
        var student = new Student
        {
            LastName = "New",
            FirstMidName = "Student",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = _controller.Create(student) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void CreatePost_ValidStudent_SavesStudentToDb()
    {
        var student = new Student
        {
            LastName = "New",
            FirstMidName = "Student",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        _controller.Create(student);

        Assert.Equal(1, _context.Students.Count());
        var saved = _context.Students.First();
        Assert.Equal("New", saved.LastName);
        Assert.Equal("Student", saved.FirstMidName);
    }

    [Fact]
    public void CreatePost_MinValueDate_AddsModelError()
    {
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "Student",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void CreatePost_DateBefore1753_AddsModelError()
    {
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "Student",
            EnrollmentDate = new DateTime(1752, 1, 1)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void CreatePost_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            FirstMidName = "Student",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.Equal(0, _context.Students.Count());
    }

    // --- Edit GET ---

    [Fact]
    public void EditGet_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void EditGet_NotFound_ReturnsNotFound()
    {
        var result = _controller.Edit(99999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void EditGet_ValidId_ReturnsViewWithStudent()
    {
        SeedStudents();
        var student = _context.Students.First();

        var result = _controller.Edit(student.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
    }

    // --- Edit POST ---

    [Fact]
    public void EditPost_ValidStudent_RedirectsToIndex()
    {
        SeedStudents();
        var existing = _context.Students.First();
        // Detach the tracked entity so the Edit can attach
        _context.Entry(existing).State = EntityState.Detached;

        var student = new Student
        {
            ID = existing.ID,
            LastName = "Updated",
            FirstMidName = "Name",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = _controller.Edit(student) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void EditPost_MinValueDate_AddsModelError()
    {
        var student = new Student
        {
            ID = 1,
            LastName = "Test",
            FirstMidName = "Student",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Edit(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void EditPost_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            ID = 1,
            LastName = "",
            FirstMidName = "Student",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = _controller.Edit(student) as ViewResult;

        Assert.NotNull(result);
    }

    // --- Delete GET ---

    [Fact]
    public void DeleteGet_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void DeleteGet_NotFound_ReturnsNotFound()
    {
        var result = _controller.Delete(99999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void DeleteGet_ValidId_ReturnsViewWithStudent()
    {
        SeedStudents();
        var student = _context.Students.First();

        var result = _controller.Delete(student.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.LastName, model.LastName);
    }

    // --- DeleteConfirmed POST ---

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesStudentAndRedirects()
    {
        SeedStudents();
        var student = _context.Students.First();
        var initialCount = _context.Students.Count();

        var result = _controller.DeleteConfirmed(student.ID) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(initialCount - 1, _context.Students.Count());
    }

    [Fact]
    public void DeleteConfirmed_ValidId_ReducesStudentCount()
    {
        SeedStudents();
        var student = _context.Students.First();
        var lastName = student.LastName;

        _controller.DeleteConfirmed(student.ID);

        Assert.Null(_context.Students.Find(student.ID));
    }

    [Fact]
    public void Index_CombinedSearchSortPage_WorksTogether()
    {
        // Seed multiple students with "Al" prefix
        for (int i = 0; i < 12; i++)
        {
            _context.Students.Add(new Student
            {
                LastName = $"Albert{i:D2}",
                FirstMidName = "Test",
                EnrollmentDate = DateTime.Today.AddDays(-i)
            });
        }
        _context.Students.Add(new Student { LastName = "Zulu", FirstMidName = "Test", EnrollmentDate = DateTime.Today });
        _context.SaveChanges();

        // Search for "Albert", sort by date descending, page 1
        var result = _controller.Index("date_desc", null, "Albert", 1) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Equal(10, model.Count); // page size = 10, 12 total matching
        Assert.True(model.HasNextPage);
        Assert.Equal(1, model.PageIndex);
    }
}

