using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;
    private readonly NotificationService _notificationService;

    public NotificationsControllerTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
        _controller = new NotificationsController(_context);
        _notificationService = new NotificationService();

        // Drain static queue to isolate tests
        while (_notificationService.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain to isolate
        while (_notificationService.ReceiveNotification() != null) { }
        _notificationService.Dispose();
        _controller.Dispose();
        _context.Dispose();
    }

    // --- GetNotifications ---

    [Fact]
    public void GetNotifications_NoNotifications_ReturnsEmptyList()
    {
        var result = _controller.GetNotifications();

        Assert.NotNull(result);
        var data = result.Value as dynamic;
        Assert.NotNull(data);
        // Use reflection to check properties on anonymous type
        var successProp = data!.GetType().GetProperty("success");
        Assert.NotNull(successProp);
        Assert.True((bool)successProp!.GetValue(data));

        var countProp = data.GetType().GetProperty("count");
        Assert.Equal(0, (int)countProp!.GetValue(data));
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsUpTo10()
    {
        // The controller uses its own notificationService (created in BaseController constructor)
        // We need to enqueue via the static queue that the controller's service shares
        var service = new NotificationService();
        for (int i = 0; i < 12; i++)
        {
            service.SendNotification("Student", i.ToString(), EntityOperation.CREATE, "Test");
        }

        var result = _controller.GetNotifications();

        var data = result.Value as dynamic;
        Assert.NotNull(data);
        var countProp = data!.GetType().GetProperty("count");
        var count = (int)countProp!.GetValue(data);
        Assert.True(count <= 10, $"Expected at most 10 notifications but got {count}");
        Assert.True(count > 0, "Expected some notifications");

        var notificationsProp = data.GetType().GetProperty("notifications");
        var notifications = notificationsProp!.GetValue(data) as List<Notification>;
        Assert.NotNull(notifications);
        Assert.True(notifications!.Count <= 10);
    }

    [Fact]
    public void GetNotifications_ReturnsSuccessTrue()
    {
        var result = _controller.GetNotifications();

        var data = result.Value as dynamic;
        Assert.NotNull(data);
        var successProp = data!.GetType().GetProperty("success");
        Assert.True((bool)successProp!.GetValue(data));
    }

    // --- MarkAsRead ---

    [Fact]
    public void MarkAsRead_ValidId_ReturnsSuccessJson()
    {
        var result = _controller.MarkAsRead(1);

        var data = result.Value as dynamic;
        Assert.NotNull(data);
        var successProp = data!.GetType().GetProperty("success");
        Assert.True((bool)successProp!.GetValue(data));
    }

    [Fact]
    public void MarkAsRead_AnyId_DoesNotThrow()
    {
        // MarkAsRead is a no-op, verify it works with any ID
        var exception = Record.Exception(() => _controller.MarkAsRead(999));
        Assert.Null(exception);
    }

    // --- Index ---

    [Fact]
    public void Index_ReturnsViewResult()
    {
        var result = _controller.Index();

        Assert.IsType<ViewResult>(result);
    }
}

using ContosoUniversity.Controllers;
