using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class DepartmentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly DepartmentsController _controller;

    public DepartmentsControllerTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
        _controller = new DepartmentsController(_context);

        _controller.TempData = new TempDataDictionary(
            new DefaultHttpContext(),
            Mock.Of<ITempDataProvider>());
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Instructor SeedInstructor(string lastName = "Fakhouri", string firstName = "Fadi")
    {
        var instructor = new Instructor
        {
            LastName = lastName,
            FirstMidName = firstName,
            HireDate = new DateTime(2002, 7, 6)
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();
        return instructor;
    }

    private Department SeedDepartment(string name = "Engineering", decimal budget = 350000m, Instructor admin = null)
    {
        var dept = new Department
        {
            Name = name,
            Budget = budget,
            StartDate = new DateTime(2007, 9, 1),
            InstructorID = admin?.ID
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    // --- Index ---

    [Fact]
    public void Index_ReturnsDepartmentsList()
    {
        var admin = SeedInstructor();
        SeedDepartment("Engineering", 350000m, admin);
        SeedDepartment("Mathematics", 100000m);

        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<Department>>(result.Model);
        Assert.Equal(2, model.Count);
        Assert.Contains(model, d => d.Name == "Engineering");
        Assert.Contains(model, d => d.Name == "Mathematics");
    }

    [Fact]
    public void Index_IncludesAdministrator()
    {
        var admin = SeedInstructor("Kapoor", "Candace");
        SeedDepartment("English", 100000m, admin);

        var result = _controller.Index() as ViewResult;

        var model = Assert.IsAssignableFrom<List<Department>>(result!.Model);
        var dept = Assert.Single(model);
        Assert.NotNull(dept.Administrator);
        Assert.Equal("Kapoor", dept.Administrator.LastName);
        Assert.Equal("Candace", dept.Administrator.FirstMidName);
    }

    [Fact]
    public void Index_NoDepartments_ReturnsEmptyList()
    {
        var result = _controller.Index() as ViewResult;

        var model = Assert.IsAssignableFrom<List<Department>>(result!.Model);
        Assert.Empty(model);
    }

    // --- Details ---

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_NotFound_ReturnsNotFound()
    {
        var result = _controller.Details(999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithDepartment()
    {
        var dept = SeedDepartment("Physics", 200000m);

        var result = _controller.Details(dept.DepartmentID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Department>(result.Model);
        Assert.Equal("Physics", model.Name);
        Assert.Equal(200000m, model.Budget);
    }

    // --- Create GET ---

    [Fact]
    public void CreateGet_PopulatesInstructorSelectList()
    {
        SeedInstructor("Zheng", "Roger");
        SeedInstructor("Abercrombie", "Kim");

        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var selectList = Assert.IsAssignableFrom<SelectList>(_controller.ViewBag.InstructorID);
        Assert.Equal(2, selectList.Count());
    }

    [Fact]
    public void CreateGet_NoInstructors_ReturnsEmptySelectList()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var selectList = Assert.IsAssignableFrom<SelectList>(_controller.ViewBag.InstructorID);
        Assert.Empty(selectList);
    }

    // --- Create POST ---

    [Fact]
    public void CreatePost_ValidDepartment_SavesAndRedirects()
    {
        var dept = new Department
        {
            Name = "Chemistry",
            Budget = 250000m,
            StartDate = new DateTime(2010, 9, 1)
        };

        var result = _controller.Create(dept) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Single(_context.Departments);
        Assert.Equal("Chemistry", _context.Departments.First().Name);
    }

    [Fact]
    public void CreatePost_ValidDepartment_AssignsBudgetCorrectly()
    {
        var dept = new Department
        {
            Name = "Biology",
            Budget = 175000m,
            StartDate = new DateTime(2015, 1, 15)
        };

        _controller.Create(dept);

        var saved = _context.Departments.Single();
        Assert.Equal(175000m, saved.Budget);
        Assert.Equal(new DateTime(2015, 1, 15), saved.StartDate);
    }

    [Fact]
    public void CreatePost_InvalidModelState_ReturnsView()
    {
        SeedInstructor();
        _controller.ModelState.AddModelError("Name", "Required");
        var dept = new Department { Budget = 100000m, StartDate = DateTime.Now };

        var result = _controller.Create(dept) as ViewResult;

        Assert.NotNull(result);
        Assert.IsType<Department>(result.Model);
        Assert.Empty(_context.Departments);
        // ViewBag should still have the instructor select list
        var selectList = Assert.IsAssignableFrom<SelectList>(_controller.ViewBag.InstructorID);
        Assert.Single(selectList);
    }

    // --- Edit GET ---

    [Fact]
    public void EditGet_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void EditGet_NotFound_ReturnsNotFound()
    {
        var result = _controller.Edit(999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void EditGet_ValidId_ReturnsViewWithDepartmentAndViewBag()
    {
        var admin = SeedInstructor("Harui", "Roger");
        var dept = SeedDepartment("Art", 50000m, admin);

        var result = _controller.Edit(dept.DepartmentID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Department>(result.Model);
        Assert.Equal("Art", model.Name);
        Assert.Equal(50000m, model.Budget);
        var selectList = Assert.IsAssignableFrom<SelectList>(_controller.ViewBag.InstructorID);
        Assert.NotEmpty(selectList);
    }

    // --- Edit POST ---

    [Fact]
    public void EditPost_ValidDepartment_UpdatesAndRedirects()
    {
        var dept = SeedDepartment("OldName", 100000m);

        // Detach so we can attach the updated entity
        _context.Entry(dept).State = EntityState.Detached;

        var updatedDept = new Department
        {
            DepartmentID = dept.DepartmentID,
            Name = "NewName",
            Budget = 200000m,
            StartDate = new DateTime(2010, 1, 1)
        };

        var result = _controller.Edit(updatedDept) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);

        // Verify the update was persisted
        var saved = _context.Departments.Find(dept.DepartmentID);
        Assert.Equal("NewName", saved!.Name);
        Assert.Equal(200000m, saved.Budget);
    }

    [Fact]
    public void EditPost_InvalidModelState_ReturnsViewWithSelectList()
    {
        SeedInstructor();
        _controller.ModelState.AddModelError("Name", "Required");
        var dept = new Department { DepartmentID = 1, Budget = 100000m, StartDate = DateTime.Now };

        var result = _controller.Edit(dept) as ViewResult;

        Assert.NotNull(result);
        Assert.IsType<Department>(result.Model);
        var selectList = Assert.IsAssignableFrom<SelectList>(_controller.ViewBag.InstructorID);
        Assert.NotEmpty(selectList);
    }

    // --- Delete GET ---

    [Fact]
    public void DeleteGet_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void DeleteGet_NotFound_ReturnsNotFound()
    {
        var result = _controller.Delete(999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void DeleteGet_ValidId_ReturnsViewWithDepartment()
    {
        var dept = SeedDepartment("History", 80000m);

        var result = _controller.Delete(dept.DepartmentID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Department>(result.Model);
        Assert.Equal("History", model.Name);
        Assert.Equal(80000m, model.Budget);
    }

    // --- DeleteConfirmed ---

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesDepartmentAndRedirects()
    {
        var dept = SeedDepartment("ToDelete", 50000m);
        Assert.Single(_context.Departments);

        var result = _controller.DeleteConfirmed(dept.DepartmentID) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Empty(_context.Departments);
    }

    [Fact]
    public void DeleteConfirmed_ValidId_ReducesDepartmentCount()
    {
        SeedDepartment("Keep", 100000m);
        var toDelete = SeedDepartment("Remove", 50000m);
        Assert.Equal(2, _context.Departments.Count());

        _controller.DeleteConfirmed(toDelete.DepartmentID);

        Assert.Single(_context.Departments);
        Assert.Equal("Keep", _context.Departments.Single().Name);
    }
}

