    private Instructor SeedInstructor(string lastName = "Fakhouri", string firstName = "Fadi",
        string officeLocation = null)
    {
        var instructor = new Instructor
        {
            LastName = lastName,
            FirstMidName = firstName,
            HireDate = new DateTime(2002, 7, 6),
            CourseAssignments = new List<CourseAssignment>()
        };
        if (officeLocation != null)
        {
            instructor.OfficeAssignment = new OfficeAssignment { Location = officeLocation };
        }
        _context.Instructors.Add(instructor);
        _context.SaveChanges();
        return instructor;
    }

    private Department SeedDepartment(string name = "Engineering", Instructor admin = null)
    {
        var dept = new Department
        {
            Name = name,
            Budget = 350000m,
            StartDate = new DateTime(2007, 9, 1),
            InstructorID = admin?.ID
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    private Course SeedCourse(int courseId, string title, int departmentId)
    {
        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = 3,
            DepartmentID = departmentId,
            Enrollments = new List<Enrollment>(),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    private void AssignCourseToInstructor(Instructor instructor, Course course)
    {
        var ca = new CourseAssignment
        {
            InstructorID = instructor.ID,
            CourseID = course.CourseID
        };
        _context.CourseAssignments.Add(ca);
        _context.SaveChanges();
    }

    private void SeedEnrollment(int courseId, string studentLastName = "Smith", Grade? grade = Grade.A)
    {
        var student = new Student
        {
            LastName = studentLastName,
            FirstMidName = "Test",
            EnrollmentDate = new DateTime(2020, 9, 1)
        };
