using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class BaseControllerTests : IDisposable
{
    private readonly SchoolContext _context;

    public BaseControllerTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
    }

    public void Dispose()
    {
        _context.Dispose();
    }

    /// <summary>
    /// Concrete subclass that exposes protected BaseController methods for testing.
    /// </summary>
    private class TestableBaseController : BaseController
    {
        public TestableBaseController(SchoolContext context) : base(context) { }

        public void PublicSendEntityNotification(string entityType, string entityId, EntityOperation op)
            => SendEntityNotification(entityType, entityId, op);

        public void PublicSendEntityNotification(string entityType, string entityId, string name, EntityOperation op)
            => SendEntityNotification(entityType, entityId, name, op);

        /// <summary>
        /// Replace the notification service with a faulty one to test error swallowing.
        /// </summary>
        public void SetFaultyNotificationService()
        {
            notificationService?.Dispose();
            notificationService = new FaultyNotificationService();
        }
    }

    /// <summary>
    /// A notification service that always throws on SendNotification.
    /// </summary>
    private class FaultyNotificationService : NotificationService
    {
        public new void SendNotification(string entityType, string entityId, string entityDisplayName,
            EntityOperation operation, string userName = null)
        {
            throw new InvalidOperationException("Simulated notification failure");
        }
    }

    // --- SendEntityNotification 3-param ---

    [Fact]
    public void SendEntityNotification_3Param_DoesNotThrow()
    {
        using var controller = new TestableBaseController(_context);

        var exception = Record.Exception(() =>
            controller.PublicSendEntityNotification("Student", "1", EntityOperation.CREATE));

        Assert.Null(exception);
    }

    [Fact]
    public void SendEntityNotification_3Param_AllOperationTypes_DoNotThrow()
    {
        using var controller = new TestableBaseController(_context);

        foreach (var op in new[] { EntityOperation.CREATE, EntityOperation.UPDATE, EntityOperation.DELETE })
        {
            var exception = Record.Exception(() =>
                controller.PublicSendEntityNotification("Course", "42", op));

            Assert.Null(exception);
        }
    }

    // --- SendEntityNotification 4-param ---

    [Fact]
    public void SendEntityNotification_4Param_DoesNotThrow()
    {
        using var controller = new TestableBaseController(_context);

        var exception = Record.Exception(() =>
            controller.PublicSendEntityNotification("Department", "5", "Engineering", EntityOperation.UPDATE));

        Assert.Null(exception);
    }

    [Fact]
    public void SendEntityNotification_4Param_NullDisplayName_DoesNotThrow()
    {
        using var controller = new TestableBaseController(_context);

        var exception = Record.Exception(() =>
            controller.PublicSendEntityNotification("Department", "5", null, EntityOperation.DELETE));

        Assert.Null(exception);
    }

    [Fact]
    public void SendEntityNotification_SwallowsExceptions()
    {
        // BaseController.SendEntityNotification catches all exceptions thrown by the notification service.
        // We test this by using a faulty service. Since BaseController wraps with try/catch,
        // the exception should NOT propagate.
        using var controller = new TestableBaseController(_context);
        controller.SetFaultyNotificationService();

        // The faulty service throws on the internal call, but BaseController catches it
        var exception = Record.Exception(() =>
            controller.PublicSendEntityNotification("Student", "1", "Test Student", EntityOperation.CREATE));

        Assert.Null(exception);
    }

    // --- Dispose ---

    [Fact]
    public void Dispose_DisposesContextAndService()
    {
        var controller = new TestableBaseController(_context);

        var exception = Record.Exception(() => controller.Dispose());

        Assert.Null(exception);
    }

    [Fact]
    public void Dispose_CalledTwice_DoesNotThrow()
    {
        var localContext = TestHelpers.CreateInMemoryContext();
        var controller = new TestableBaseController(localContext);

        controller.Dispose();

        var exception = Record.Exception(() => controller.Dispose());

        Assert.Null(exception);
    }
}

