19.     {
20.         _context = TestHelpers.CreateInMemoryContext();
21.         _controller = new StudentsController(_context);
22. 
23.         // Set up TempData for controller
24.         _controller.TempData = new TempDataDictionary(
25.             new DefaultHttpContext(),
