35.     private void SeedStudents()
36.     {
37.         _context.Students.AddRange(
38.             new Student { LastName = "Alexander", FirstMidName = "Carson", EnrollmentDate = new DateTime(2020, 9, 1) },
39.             new Student { LastName = "Alonso", FirstMidName = "Meredith", EnrollmentDate = new DateTime(2021, 9, 1) },
40.             new Student { LastName = "Barzdukas", FirstMidName = "Gytis", EnrollmentDate = new DateTime(2019, 9, 1) },
41.             new Student { LastName = "Li", FirstMidName = "Yan", EnrollmentDate = new DateTime(2022, 9, 1) },
42.             new Student { LastName = "Justice", FirstMidName = "Peggy", EnrollmentDate = new DateTime(2020, 9, 1) }
43.         );
44.         _context.SaveChanges();
45.     }
46. 
47.     // --- Index ---
48. 
49.     [Fact]
50.     public void Index_NoParams_ReturnsViewWithStudentsOrderedByLastName()
51.     {
52.         SeedStudents();
53. 
54.         var result = _controller.Index(null, null, null, null) as ViewResult;
55. 
56.         Assert.NotNull(result);
57.         var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
58.         Assert.Equal(5, model.Count);
59.         // Default sort is OrderBy(LastName) ascending
60.         Assert.Equal("Alexander", model[0].LastName);
61.         Assert.Equal("Alonso", model[1].LastName);
62.         Assert.Equal("Barzdukas", model[2].LastName);
63.         Assert.Equal("Justice", model[3].LastName);
64.         Assert.Equal("Li", model[4].LastName);
65.     }
66. 
67.     [Fact]
68.     public void Index_NameDescSort_ReturnsStudentsDescendingByLastName()
69.     {
70.         SeedStudents();
71. 
72.         var result = _controller.Index("name_desc", null, null, null) as ViewResult;
73. 
74.         var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
75.         Assert.Equal("Li", model[0].LastName);
76.         Assert.Equal("Justice", model[1].LastName);
77.         Assert.Equal("Barzdukas", model[2].LastName);
78.     }
