    [Fact]
    public void Dispose_CalledMultipleTimes_DoesNotThrow()
    {
        // Arrange
        var service = new NotificationService();

        // Act & Assert
        var exception = Record.Exception(() =>
        {
            service.Dispose();
            service.Dispose();
        });
        Assert.Null(exception);
    }

    // --- Queue eviction (max length = 500) ---

    [Fact]
    public void SendNotification_QueueExceedsMaxLength_EvictsOldest()
    {
        // Arrange — enqueue 505 notifications; the cap is 500
        for (int i = 0; i < 505; i++)
        {
            _service.SendNotification("Item", i.ToString(), EntityOperation.CREATE, "Tester");
        }

        // Act — drain everything and count
        var received = new List<Notification>();
        Notification n;
        while ((n = _service.ReceiveNotification()) != null)
        {
            received.Add(n);
        }

        // Assert — queue should have been capped at 500 (some oldest evicted)
        Assert.True(received.Count <= 500,
            $"Queue should be capped at 500 but had {received.Count} items");
        Assert.True(received.Count >= 498,
            $"Queue should contain close to 500 items but had {received.Count}");

        // The earliest surviving notification should NOT be item "0" — that was evicted
        var firstId = received[0].EntityId;
        Assert.NotEqual("0", firstId);

        // The last notification should be the most recently enqueued
        Assert.Equal("504", received[^1].EntityId);
    }

    // --- Default switch case ---

    [Fact]
    public void SendNotification_DefaultSwitchCase_ReturnsGenericMessage()
    {
        // Arrange — cast an invalid int to EntityOperation to hit the default branch
        var invalidOp = (EntityOperation)999;

        // Act
        _service.SendNotification("Widget", "42", "TestWidget", invalidOp, "Admin");
        var notification = _service.ReceiveNotification();

        // Assert — default case produces "{displayText} operation: {operation}"
        Assert.NotNull(notification);
        Assert.Contains("operation:", notification.Message);
        Assert.Contains("999", notification.Message);
        // Verify it does NOT contain standard action phrases
        Assert.DoesNotContain("has been created", notification.Message);
        Assert.DoesNotContain("has been updated", notification.Message);
        Assert.DoesNotContain("has been deleted", notification.Message);
        // Operation field should be the int's ToString
        Assert.Equal("999", notification.Operation);
    }
}

