using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Xunit;

namespace ContosoUniversity.Tests.Models;

public class ViewModelTests
{
    // --- AssignedCourseData ---

    [Fact]
    public void AssignedCourseData_Properties_CanBeSetAndRetrieved()
    {
        var data = new AssignedCourseData
        {
            CourseID = 1050,
            Title = "Chemistry",
            Assigned = true
        };

        Assert.Equal(1050, data.CourseID);
        Assert.Equal("Chemistry", data.Title);
        Assert.True(data.Assigned);
    }

    [Fact]
    public void AssignedCourseData_DefaultAssigned_IsFalse()
    {
        var data = new AssignedCourseData();

        Assert.False(data.Assigned);
        Assert.Equal(0, data.CourseID);
        Assert.Null(data.Title);
    }

    [Fact]
    public void AssignedCourseData_DifferentCourses_HaveDistinctValues()
    {
        var assigned = new AssignedCourseData { CourseID = 101, Title = "Math", Assigned = true };
        var unassigned = new AssignedCourseData { CourseID = 202, Title = "History", Assigned = false };

        Assert.NotEqual(assigned.CourseID, unassigned.CourseID);
        Assert.NotEqual(assigned.Title, unassigned.Title);
        Assert.NotEqual(assigned.Assigned, unassigned.Assigned);
    }

    // --- EnrollmentDateGroup ---

    [Fact]
    public void EnrollmentDateGroup_Properties_CanBeSetAndRetrieved()
    {
        var group = new EnrollmentDateGroup
        {
            EnrollmentDate = new DateTime(2020, 9, 1),
            StudentCount = 15
        };

        Assert.Equal(new DateTime(2020, 9, 1), group.EnrollmentDate);
        Assert.Equal(15, group.StudentCount);
    }

    [Fact]
    public void EnrollmentDateGroup_NullableDate_CanBeNull()
    {
        var group = new EnrollmentDateGroup
        {
            EnrollmentDate = null,
            StudentCount = 3
        };

        Assert.Null(group.EnrollmentDate);
        Assert.Equal(3, group.StudentCount);
    }

    [Fact]
    public void EnrollmentDateGroup_DefaultValues_AreZeroAndNull()
    {
        var group = new EnrollmentDateGroup();

        Assert.Null(group.EnrollmentDate);
        Assert.Equal(0, group.StudentCount);
    }

    // --- InstructorIndexData ---

    [Fact]
    public void InstructorIndexData_Properties_CanBeSetAndRetrieved()
    {
        var instructors = new List<Instructor>
        {
            new Instructor { LastName = "Smith", FirstMidName = "John", HireDate = DateTime.Today }
        };
        var courses = new List<Course>
        {
            new Course { CourseID = 101, Title = "Math", Credits = 3 }
        };
        var enrollments = new List<Enrollment>
        {
            new Enrollment { EnrollmentID = 1, CourseID = 101, StudentID = 1, Grade = Grade.A }
        };

        var data = new InstructorIndexData
        {
            Instructors = instructors,
            Courses = courses,
            Enrollments = enrollments
        };

        Assert.Single(data.Instructors);
        Assert.Equal("Smith", data.Instructors.First().LastName);
        Assert.Single(data.Courses);
        Assert.Equal(101, data.Courses.First().CourseID);
        Assert.Single(data.Enrollments);
        Assert.Equal(Grade.A, data.Enrollments.First().Grade);
    }

    [Fact]
    public void InstructorIndexData_DefaultValues_AreNull()
    {
        var data = new InstructorIndexData();

        Assert.Null(data.Instructors);
        Assert.Null(data.Courses);
        Assert.Null(data.Enrollments);
    }

    [Fact]
    public void InstructorIndexData_EmptyCollections_AreEmpty()
    {
        var data = new InstructorIndexData
        {
            Instructors = Enumerable.Empty<Instructor>(),
            Courses = Enumerable.Empty<Course>(),
            Enrollments = Enumerable.Empty<Enrollment>()
        };

        Assert.Empty(data.Instructors);
        Assert.Empty(data.Courses);
        Assert.Empty(data.Enrollments);
    }
}

using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests.Models;

public class ModelPropertyTests
{
    // --- Course ---

    [Fact]
    public void Course_AllProperties_CanBeSetAndRetrieved()
    {
        var dept = new Department { DepartmentID = 7, Name = "Science" };
        var enrollment = new Enrollment { EnrollmentID = 1, CourseID = 2001, StudentID = 1 };
        var assignment = new CourseAssignment { CourseID = 2001, InstructorID = 5 };

        var course = new Course
        {
            CourseID = 2001,
            Title = "Advanced Physics",
            Credits = 4,
            DepartmentID = 7,
            TeachingMaterialImagePath = "/Uploads/physics.png",
            Department = dept,
            Enrollments = new List<Enrollment> { enrollment },
            CourseAssignments = new List<CourseAssignment> { assignment }
        };

        Assert.Equal(2001, course.CourseID);
        Assert.Equal("Advanced Physics", course.Title);
        Assert.Equal(4, course.Credits);
        Assert.Equal(7, course.DepartmentID);
        Assert.Equal("/Uploads/physics.png", course.TeachingMaterialImagePath);
        Assert.Same(dept, course.Department);
        Assert.Single(course.Enrollments);
        Assert.Single(course.CourseAssignments);
    }

    [Fact]
    public void Course_DefaultImagePath_IsNull()
    {
        var course = new Course { CourseID = 100, Title = "Basic", Credits = 1 };

        Assert.Null(course.TeachingMaterialImagePath);
    }

    [Fact]
    public void Course_NavigationProperties_DefaultNull()
    {
        var course = new Course();

        Assert.Null(course.Department);
        Assert.Null(course.Enrollments);
        Assert.Null(course.CourseAssignments);
    }

    // --- Department ---

    [Fact]
    public void Department_AllProperties_CanBeSetAndRetrieved()
    {
        var admin = new Instructor { LastName = "Doe", FirstMidName = "Jane", HireDate = DateTime.Today };
        var course = new Course { CourseID = 300, Title = "Algebra", Credits = 3 };
        var rowVersion = new byte[] { 0x01, 0x02, 0x03 };

        var dept = new Department
        {
            DepartmentID = 10,
            Name = "Mathematics",
            Budget = 250000m,
            StartDate = new DateTime(2010, 9, 1),
            InstructorID = 42,
            RowVersion = rowVersion,
            Administrator = admin,
            Courses = new List<Course> { course }
        };

        Assert.Equal(10, dept.DepartmentID);
        Assert.Equal("Mathematics", dept.Name);
        Assert.Equal(250000m, dept.Budget);
        Assert.Equal(new DateTime(2010, 9, 1), dept.StartDate);
        Assert.Equal(42, dept.InstructorID);
        Assert.Same(rowVersion, dept.RowVersion);
        Assert.Same(admin, dept.Administrator);
        Assert.Single(dept.Courses);
        Assert.Equal("Algebra", dept.Courses.First().Title);
    }

    [Fact]
    public void Department_InstructorID_IsNullable()
    {
        var dept = new Department
        {
            Name = "NoAdmin",
            Budget = 100000m,
            StartDate = DateTime.Today,
            InstructorID = null
        };

        Assert.Null(dept.InstructorID);
    }

    // --- Instructor ---

    [Fact]
    public void Instructor_HireDateAndCollections_CanBeSetAndRetrieved()
    {
        var office = new OfficeAssignment { InstructorID = 1, Location = "Room 301" };
        var assignment = new CourseAssignment { InstructorID = 1, CourseID = 500 };

        var instructor = new Instructor
        {
            ID = 1,
            LastName = "Smith",
            FirstMidName = "John",
            HireDate = new DateTime(2015, 8, 20),
            CourseAssignments = new List<CourseAssignment> { assignment },
            OfficeAssignment = office
        };

        Assert.Equal(new DateTime(2015, 8, 20), instructor.HireDate);
        Assert.Single(instructor.CourseAssignments);
        Assert.Equal(500, instructor.CourseAssignments.First().CourseID);
        Assert.NotNull(instructor.OfficeAssignment);
        Assert.Equal("Room 301", instructor.OfficeAssignment.Location);
    }

    [Fact]
    public void Instructor_DefaultCollections_AreNull()
    {
        var instructor = new Instructor();

        Assert.Null(instructor.CourseAssignments);
        Assert.Null(instructor.OfficeAssignment);
    }

    // --- Notification ---

    [Fact]
    public void Notification_AllProperties_CanBeSetAndRetrieved()
    {
        var createdAt = new DateTime(2024, 5, 10, 14, 30, 0);

        var notification = new Notification
        {
            Id = 42,
            EntityType = "Student",
            EntityId = "123",
            Operation = "CREATE",
            Message = "New Student has been created",
            CreatedAt = createdAt,
            CreatedBy = "Admin",
            IsRead = true
        };

        Assert.Equal(42, notification.Id);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("123", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("New Student has been created", notification.Message);
        Assert.Equal(createdAt, notification.CreatedAt);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.True(notification.IsRead);
    }

    [Fact]
    public void Notification_DefaultIsRead_IsFalse()
    {
        var notification = new Notification();

        Assert.False(notification.IsRead);
        Assert.Equal(0, notification.Id);
        Assert.Null(notification.EntityType);
        Assert.Null(notification.CreatedBy);
    }

    // --- Enrollment ---

    [Fact]
    public void Enrollment_AllProperties_CanBeSetAndRetrieved()
    {
        var course = new Course { CourseID = 1050, Title = "Chemistry", Credits = 3 };
        var student = new Student
        {
            LastName = "Jones",
            FirstMidName = "Alex",
            EnrollmentDate = DateTime.Today
        };

        var enrollment = new Enrollment
        {
            EnrollmentID = 7,
            CourseID = 1050,
            StudentID = 99,
            Grade = Grade.B,
            Course = course,
            Student = student
        };

        Assert.Equal(7, enrollment.EnrollmentID);
        Assert.Equal(1050, enrollment.CourseID);
        Assert.Equal(99, enrollment.StudentID);
        Assert.Equal(Grade.B, enrollment.Grade);
        Assert.Same(course, enrollment.Course);
        Assert.Same(student, enrollment.Student);
    }

    [Fact]
    public void Enrollment_Grade_IsNullable()
    {
        var enrollment = new Enrollment
        {
            CourseID = 1050,
            StudentID = 1,
            Grade = null
        };

        Assert.Null(enrollment.Grade);
    }

    // --- Grade enum ---

    [Theory]
    [InlineData(Grade.A, 0)]
    [InlineData(Grade.B, 1)]
    [InlineData(Grade.C, 2)]
    [InlineData(Grade.D, 3)]
    [InlineData(Grade.F, 4)]
    public void Grade_EnumValues_HaveExpectedIntValues(Grade grade, int expectedValue)
    {
        Assert.Equal(expectedValue, (int)grade);
    }

    [Fact]
    public void Grade_Enum_HasExactly5Values()
    {
        var values = Enum.GetValues<Grade>();

        Assert.Equal(5, values.Length);
        Assert.Contains(Grade.A, values);
        Assert.Contains(Grade.B, values);
        Assert.Contains(Grade.C, values);
        Assert.Contains(Grade.D, values);
        Assert.Contains(Grade.F, values);
    }

    [Fact]
    public void Grade_Enum_DoesNotContainE()
    {
        // Verify the grade scale skips E (A, B, C, D, F — no E)
        var names = Enum.GetNames<Grade>();
        Assert.DoesNotContain("E", names);
    }
}

